import{_ as c,C as r,o as n,c as i,ai as d,E as e}from"./chunks/framework.C7mMih4h.js";const f=JSON.parse('{"title":"ConfigProvider 全局配置","description":"","frontmatter":{"title":"ConfigProvider 全局配置","outline":[2,3]},"headers":[],"relativePath":"components/config-provider.md","filePath":"components/config-provider.md","lastUpdated":1791429948000}'),a={name:"components/config-provider.md"};function s(l,t,p,g,m,h){const o=r("DemoPreview");return n(),i("div",null,[t[0]||(t[0]=d('<div><p>为整个子树统一提供<strong>主题</strong>、<strong>语言</strong>、<strong>尺寸</strong>、<strong>禁用</strong>、<strong>类名前缀</strong>等运行时配置。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>应用级一次性包住根组件（或大型特性区域的入口），让下游所有组件自动跟随。</li><li>想切换语言、暗色主题、紧凑模式、组件前缀……都从这里入手。</li><li>想覆盖某个组件的默认 props（<code>Empty</code> 的 <code>description</code>、<code>Spin</code> 的 <code>indicator</code>、……）用 <code>components.xxx</code> 字段。</li></ul></div><h2 id="代码演示" tabindex="-1">代码演示 <a class="header-anchor" href="#代码演示" aria-label="Permalink to &quot;代码演示&quot;">​</a></h2><div><p><strong>component-config</strong>：已落地的组件（<code>empty</code> / <code>divider</code> / <code>spin</code> / <code>form</code>）有<strong>精确类型</strong>的 prop； 其余组件走 <code>components</code> 弱类型逃生口：</p></div>',3)),e(o,{component:"config-provider",demo:"component-config"}),t[1]||(t[1]=d("<div><p><strong>locale</strong>：<code>locale</code> 会传导到整棵子树，下游组件用 <code>useLocale(&#39;&lt;ComponentName&gt;&#39;)</code> 读取。 语言包来自 <code>@apollo-design/locale</code>（73 个，从 antd 6.6.4 的 <code>es/locale/*</code> 生成）。 <code>ComponentName</code> 与 antd 一致：<code>Empty</code> / <code>Table</code> / <code>Form</code> / <code>Pagination</code> … ⚠️ 已知限制：<code>useLocale</code> 目前<strong>不是响应式</strong>的（<code>locale</code> 包的设计未决项 D24）， 切换 <code>locale</code> 后需要让子树重新挂载才能拿到新文案。 <code>ConfigProvider</code> 这一侧的接线是响应式的（context 里的值会立刻变）。</p></div>",1)),e(o,{component:"config-provider",demo:"locale"}),t[2]||(t[2]=d("<div><p><strong>prefix-cls</strong>：<code>prefixCls</code> 会传给整棵子树，且<strong>内层没给时继承外层</strong>（与 antd 的 <code>nest prefixCls</code> 行为一致）。 默认值是 <code>apollo</code>（裁决 <code>prefix-cls-default</code> = A）。静态 CSS 同时为 <code>apollo</code> 与 <code>ant</code> 两份前缀生成了产物，所以设成 <code>ant</code> 可以复用既有样式。 ⚠️ 自定义前缀（如 <code>my-app</code>）需要自行产出 CSS： <code>genComponentCss(&#39;empty&#39;, &#39;my-app&#39;)</code> —— 零运行时的固有代价。</p></div>",1)),e(o,{component:"config-provider",demo:"prefix-cls"}),t[3]||(t[3]=d('<div><p><strong>size-disabled</strong>：<code>componentSize</code> 与 <code>componentDisabled</code> 是<strong>两条独立的 context</strong>（与 antd 同）， 下游用 <code>useSize()</code> / <code>useDisabled()</code> / <code>useConfig()</code> 读取。 两条判据<strong>不同</strong>，不能统一（这是最容易写错的地方）：</p><table tabindex="0"><thead><tr><th>开关</th><th>判据</th><th>为什么</th></tr></thead><tbody><tr><td><code>componentSize</code></td><td><code>componentSize || 父级</code></td><td>未设置就继承</td></tr><tr><td><code>componentDisabled</code></td><td><code>componentDisabled ?? 父级</code></td><td><code>false</code> 必须能<strong>显式关闭</strong>父级的 <code>true</code></td></tr><tr><td>⚠️ 返回值是 <code>ComputedRef</code>（要 <code>.value</code>），不是 antd 那样的裸值 ——</td><td></td><td></td></tr><tr><td>裸值在 Vue 里等于把配置在 setup 期定死（差异 D27）。</td><td></td><td></td></tr></tbody></table></div>',1)),e(o,{component:"config-provider",demo:"size-disabled"}),t[4]||(t[4]=d("<div><p><strong>theme</strong>：<code>theme</code> 支持 <code>token</code> / <code>algorithm</code> / <code>components</code> / <code>cssVarPrefix</code> / <code>inherit</code>， 合并语义与 antd 的 <code>useTheme</code> 一致（嵌套时 <code>token</code> 浅合并、<code>components</code> 逐组件合并； <code>inherit: false</code> 时不继承外层）。 <strong>它是怎么生效的</strong>：<code>ConfigProvider</code> 调 <code>getDesignToken()</code> 算出完整 token， 再用 <code>createCSSVarScope()</code> 把 <code>--apollo-*</code> 写到作用域元素上。 静态 CSS 只引用 <code>var(--apollo-*)</code>，所以主题切换<strong>零样式重算</strong>。 ⚠️ 两处已知限制：</p><ol><li><code>theme.components</code>（Component Token）目前只进 context，<strong>不产出 CSS 变量</strong> —— <code>tokens.css</code> 只声明 Alias 层（PITFALLS 92）。</li><li>给了 <code>theme</code> 时，为了让 CSS 变量有地方挂，会多渲染一个 <code>display: contents</code> 的作用域元素（不产生布局盒）。差异登记为 <strong>D26</strong>。</li></ol></div>",1)),e(o,{component:"config-provider",demo:"theme"}),t[5]||(t[5]=d('<div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td>prefixCls</td><td>全局类名前缀</td><td><code>string</code></td><td><code>&#39;apollo&#39;</code></td></tr><tr><td>iconPrefixCls</td><td>图标类名前缀</td><td><code>string</code></td><td><code>&#39;anticon&#39;</code>（与 antd 对齐）</td></tr><tr><td>getPopupContainer</td><td>浮层（弹窗/Tooltip 等）的父元素</td><td><code>(trigger?: HTMLElement) =&gt; HTMLElement | ShadowRoot</code></td><td>—</td></tr><tr><td>getTargetContainer</td><td>通知/消息等「全屏感知」容器的查找函数</td><td><code>() =&gt; HTMLElement | Window | ShadowRoot</code></td><td>—</td></tr><tr><td>renderEmpty</td><td>自定义空状态渲染函数。antd 的 Table / List / Select 等无内容时会调它</td><td><code>(componentName?: &#39;Table&#39; | &#39;Table.filter&#39; | &#39;List&#39; | &#39;Select&#39; | &#39;TreeSelect&#39; | &#39;Cascader&#39; | &#39;Transfer&#39; | &#39;Mentions&#39;) =&gt; unknown</code></td><td><code>defaultRenderEmpty</code></td></tr><tr><td>componentSize</td><td>下游「组件尺寸」统一值（<code>&#39;small&#39; | &#39;medium&#39; | &#39;middle&#39; | &#39;large&#39;</code>）</td><td><code>SizeType</code></td><td>—</td></tr><tr><td>componentDisabled</td><td>下游「组件禁用」统一值</td><td><code>boolean</code></td><td>—</td></tr><tr><td>direction</td><td>文本方向</td><td><code>&#39;ltr&#39; | &#39;rtl&#39;</code></td><td>—</td></tr><tr><td>locale</td><td>语言包</td><td><code>Locale</code>（<code>@apollo-design/locale</code>）</td><td>—</td></tr><tr><td>theme</td><td>主题配置</td><td><code>{ token?: Record&lt;string, any&gt;; components?: Record&lt;string, any&gt;; algorithm?: MappingAlgorithm; cssVarPrefix?: string; prefixCls?: string; inherit?: boolean }</code></td><td>—</td></tr><tr><td>csp</td><td>CSP nonce</td><td><code>{ nonce?: string }</code></td><td>—</td></tr><tr><td>variant</td><td>组件形态（<code>&#39;outlined&#39; | &#39;borderless&#39; | &#39;filled&#39; | &#39;underlined&#39;</code>）</td><td><code>Variant</code></td><td>—</td></tr><tr><td>virtual</td><td>是否启用虚拟滚动</td><td><code>boolean</code></td><td><code>true</code></td></tr><tr><td>popupMatchSelectWidth</td><td>下拉与触发器同宽</td><td><code>boolean</code></td><td>—</td></tr><tr><td>popupOverflow</td><td>浮层超出视口时的行为</td><td><code>&#39;viewport&#39; | &#39;scroll&#39;</code></td><td>—</td></tr><tr><td>wave</td><td>波纹效果</td><td><code>{ disabled?: boolean; triggerType?: &#39;click&#39; | &#39;pointerdown&#39; | ... }</code></td><td>—</td></tr><tr><td>warning</td><td>告警开关</td><td><code>{ strict?: boolean; false?: boolean; ... }</code></td><td><code>{}</code></td></tr><tr><td>form</td><td>表单配置</td><td><code>{ validateMessages?: ValidateMessages | ((values) =&gt; ValidateMessages); requiredMark?: boolean; colon?: boolean }</code></td><td>—</td></tr><tr><td>divider</td><td><code>Divider</code> 默认 props</td><td><code>Partial&lt;DividerProps&gt;</code></td><td>—</td></tr><tr><td>empty</td><td><code>Empty</code> 默认 props</td><td><code>Partial&lt;EmptyProps&gt;</code></td><td>—</td></tr><tr><td>spin</td><td><code>Spin</code> 默认 props</td><td><code>Partial&lt;SpinProps&gt;</code></td><td>—</td></tr><tr><td>components</td><td>其余 53 个组件的默认 props 逃生口（弱类型）</td><td><code>Record&lt;string, any&gt;</code></td><td>—</td></tr></tbody></table><h3 id="废弃属性" tabindex="-1">废弃属性 <a class="header-anchor" href="#废弃属性" aria-label="Permalink to &quot;废弃属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>旧名</th><th>新名</th></tr></thead><tbody><tr><td><code>autoInsertSpaceInButton</code></td><td><code>components.button.autoInsertSpace</code></td></tr><tr><td><code>dropdownMatchSelectWidth</code></td><td><code>popupMatchSelectWidth</code></td></tr></tbody></table><h3 id="静态属性-具名导出" tabindex="-1">静态属性 / 具名导出 <a class="header-anchor" href="#静态属性-具名导出" aria-label="Permalink to &quot;静态属性 / 具名导出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td><code>ConfigProvider.ConfigContext</code></td><td><code>useContext</code> 形态的 context（一般请用 <code>useConfig</code>）</td></tr><tr><td><code>ConfigProvider.config</code></td><td><code>getConfig()</code>：取当前的 <code>ConfigContext</code></td></tr><tr><td><code>ConfigProvider.useConfig</code></td><td><code>useConfig()</code>：取 <code>{ componentDisabled, componentSize }</code></td></tr></tbody></table><h2 id="与-antd-的差异" tabindex="-1">与 antd 的差异 <a class="header-anchor" href="#与-antd-的差异" aria-label="Permalink to &quot;与 antd 的差异&quot;">​</a></h2><p>完整列表见 <a href="./../../../../../../../docs/analysis/config-provider.html"><code>docs/analysis/config-provider.md</code> §9</a>，要点：</p><ul><li><strong><code>components</code> 的类型是渐进式</strong>：已落地的三个组件（<code>divider</code> / <code>empty</code> / <code>spin</code>）有精确 prop；其余 53 个走 <code>Record&lt;string, any&gt;</code> 逃生口，等对应组件落地再补精确类型。</li><li><strong><code>theme</code> 给出时会渲染一个 <code>display: contents</code> 的作用域元素承载 CSS 变量</strong>。对布局零影响，但在 Chromium 的 <code>#stage</code> 这类 inline 容器里会让 stage 高 1px（D32，不修）。</li><li><strong><code>direction</code> 的读取必须用 <code>useDirection()</code></strong>：<code>inject</code> 只在 setup 解析一次，解构 <code>useComponentConfig()</code> 拿到的 <code>direction</code> 是快照。</li><li><strong>不提供</strong> <code>tooltip</code> / <code>popover</code> / <code>popconfirm</code> prop（依赖 <code>UniqueProvider</code>，未实现）。</li></ul></div>',1))])}const u=c(a,[["render",s]]);export{f as __pageData,u as default};
